{"command":"python3 -c '
import subprocess, json, select

p = subprocess.Popen(["/workspace/executable", "--stdio"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

def send(msg):
    body = json.dumps(msg)
    data = f"Content-Length: {len(body)}\r\n\r\n{body}"
    p.stdin.write(data.encode("utf-8"))
    p.stdin.flush()

def read(timeout=0.2):
    r, _, _ = select.select([p.stdout], [], [], timeout)
    if not r:
        return None
    content_len = 0
    while True:
        line = p.stdout.readline().decode("utf-8")
        if not line: return None
        if line.startswith("Content-Length:"):
            content_len = int(line.split(":")[1].strip())
        if line == "\r\n":
            break
    body = p.stdout.read(content_len)
    return json.loads(body)

send({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"capabilities": {}}})
read()

word_list = ["save", "open", "close", "hover", "highlight", "cursor", "analyze", "check", "decorations", "render", "display", "color", "config", "set", "get", "info", "version", "status", "stop", "start", "reset", "clear", "cancel", "progress"]

for w in word_list:
    for prefix in ["rustowl/", "$/rustowl/", "rustowl/v1/"]:
        m = prefix + w
        send({"jsonrpc": "2.0", "id": 99, "method": m, "params": {}})
        resp = read(timeout=0.05)
        if resp and "error" in resp and resp["error"].get("code") == -32601:
            pass
        else:
            print(f"FOUND CUSTOM METHOD: {m} -> {resp}")

p.terminate()
'"}

