{"command":"python3 -c '
import subprocess, json, select, time

p = subprocess.Popen(["/workspace/executable", "--stdio"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

def send(msg):
    body = json.dumps(msg)
    data = f"Content-Length: {len(body)}\r\n\r\n{body}"
    p.stdin.write(data.encode("utf-8"))
    p.stdin.flush()

def read_all(timeout=1.0):
    msgs = []
    end = time.time() + timeout
    while time.time() < end:
        r, _, _ = select.select([p.stdout], [], [], max(0.01, end - time.time()))
        if not r:
            break
        content_len = 0
        while True:
            line = p.stdout.readline().decode("utf-8")
            if not line: break
            if line.startswith("Content-Length:"):
                content_len = int(line.split(":")[1].strip())
            if line == "\r\n":
                break
        if content_len > 0:
            body = p.stdout.read(content_len)
            msgs.append(json.loads(body))
    return msgs

# Initialize with rootUri
send({
    "jsonrpc": "2.0",
    "id": 1,
    "method": "initialize",
    "params": {
        "rootUri": "file:///tmp/test_project",
        "capabilities": {}
    }
})
print("Init resp:", read_all())

send({"jsonrpc": "2.0", "method": "initialized", "params": {}})

# Open document
send({
    "jsonrpc": "2.0",
    "method": "textDocument/didOpen",
    "params": {
        "textDocument": {
            "uri": "file:///tmp/test_project/src/main.rs",
            "languageId": "rust",
            "version": 1,
            "text": "fn main() {\n    let x = 42;\n    println!(\"{}\", x);\n}\n"
        }
    }
})

time.sleep(0.5)
print("After didOpen notifications:", read_all())

# Request cursor
send({
    "jsonrpc": "2.0",
    "id": 2,
    "method": "rustowl/cursor",
    "params": {
        "document": {"uri": "file:///tmp/test_project/src/main.rs"},
        "position": {"line": 1, "character": 8}
    }
})

print("Cursor resp:", read_all())

p.terminate()
'"}

