{"command":"cat << 'EOF' > src/logger.rs
use chrono::Utc;
use std::sync::atomic::{AtomicUsize, Ordering};

static QUIET_LEVEL: AtomicUsize = AtomicUsize::new(0);

#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub enum LogLevel {
    Trace = 0,
    Debug = 1,
    Info = 2,
    Warn = 3,
    Error = 4,
}

pub fn set_quiet_level(level: usize) {
    QUIET_LEVEL.store(level, Ordering::SeqCst);
}

pub fn get_quiet_level() -> usize {
    QUIET_LEVEL.load(Ordering::SeqCst)
}

pub fn log(level: LogLevel, target: &str, msg: &str) {
    let quiet = get_quiet_level();
    let min_level = match quiet {
        0 => LogLevel::Info,
        1 => LogLevel::Warn,
        2 => LogLevel::Error,
        _ => return,
    };

    if (level as u8) < (min_level as u8) {
        return;
    }

    let level_str = match level {
        LogLevel::Trace => "TRACE",
        LogLevel::Debug => "DEBUG",
        LogLevel::Info => "INFO ",
        LogLevel::Warn => "WARN ",
        LogLevel::Error => "ERROR",
    };

    let now = Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ");
    eprintln!("{} {} [{}] {}", now, level_str, target, msg);
}

#[macro_export]
macro_rules! log_info {
    ($target:expr, $($arg:tt)*) => {
        $crate::logger::log($crate::logger::LogLevel::Info, $target, &format!($($arg)*));
    };
}

#[macro_export]
macro_rules! log_warn {
    ($target:expr, $($arg:tt)*) => {
        $crate::logger::log($crate::logger::LogLevel::Warn, $target, &format!($($arg)*));
    };
}

#[macro_export]
macro_rules! log_error {
    ($target:expr, $($arg:tt)*) => {
        $crate::logger::log($crate::logger::LogLevel::Error, $target, &format!($($arg)*));
    };
}
EOF"}

