use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::io::{BufRead, BufReader, Read, Write};

pub fn run_lsp_server() {
    eprintln!("RustOwl v1.0.0-rc.1");
    eprintln!("This is an LSP server. You can use --help flag to show help.");

    let stdin = std::io::stdin();
    let mut reader = BufReader::new(stdin.lock());
    let mut stdout = std::io::stdout();

    let mut is_initialized = false;

    loop {
        let mut content_length: usize = 0;

        // Read headers
        loop {
            let mut line = String::new();
            match reader.read_line(&mut line) {
                Ok(0) => return, // EOF
                Ok(_) => {}
                Err(_) => return,
            }

            let trimmed = line.trim();
            if trimmed.is_empty() {
                break; // Blank line signals end of headers
            }

            if line.to_lowercase().starts_with("content-length:") {
                if let Some(val) = line.split(':').nth(1) {
                    content_length = val.trim().parse::<usize>().unwrap_or(0);
                }
            }
        }

        if content_length == 0 {
            continue;
        }

        // Read body
        let mut body_buf = vec![0u8; content_length];
        if reader.read_exact(&mut body_buf).is_err() {
            return;
        }

        let msg_val: Value = match serde_json::from_slice(&body_buf) {
            Ok(v) => v,
            Err(_) => {
                let err_resp = json!({
                    "jsonrpc": "2.0",
                    "id": Value::Null,
                    "error": {
                        "code": -32700,
                        "message": "Parse error"
                    }
                });
                send_response(&mut stdout, &err_resp);
                continue;
            }
        };

        let method = msg_val.get("method").and_then(|m| m.as_str());
        let id = msg_val.get("id").cloned();

        match method {
            Some("initialize") => {
                let resp = json!({
                    "jsonrpc": "2.0",
                    "id": id,
                    "result": {
                        "capabilities": {
                            "textDocumentSync": {
                                "change": 2,
                                "openClose": true,
                                "save": true
                            },
                            "workspace": {
                                "workspaceFolders": {
                                    "changeNotifications": true,
                                    "supported": true
                                }
                            }
                        }
                    }
                });
                send_response(&mut stdout, &resp);
            }
            Some("initialized") => {
                is_initialized = true;
            }
            Some("shutdown") => {
                let resp = json!({
                    "jsonrpc": "2.0",
                    "id": id,
                    "result": Value::Null
                });
                send_response(&mut stdout, &resp);
            }
            Some("exit") => {
                std::process::exit(0);
            }
            Some("rustowl/cursor") => {
                if let Some(id) = id {
                    if !is_initialized {
                        let resp = json!({
                            "jsonrpc": "2.0",
                            "id": id,
                            "error": {
                                "code": -32002,
                                "message": "Server not initialized"
                            }
                        });
                        send_response(&mut stdout, &resp);
                        continue;
                    }

                    let params = msg_val.get("params");
                    let pos_val = params.and_then(|p| p.get("position"));
                    let doc_val = params.and_then(|p| p.get("document"));

                    if pos_val.is_none() {
                        let resp = json!({
                            "jsonrpc": "2.0",
                            "id": id,
                            "error": {
                                "code": -32602,
                                "message": if pos_val.map_or(false, |v| v.is_null()) {
                                    "invalid type: null, expected struct Position"
                                } else {
                                    "missing field `position`"
                                }
                            }
                        });
                        send_response(&mut stdout, &resp);
                        continue;
                    }

                    if doc_val.is_none() {
                        let resp = json!({
                            "jsonrpc": "2.0",
                            "id": id,
                            "error": {
                                "code": -32602,
                                "message": "missing field `document`"
                            }
                        });
                        send_response(&mut stdout, &resp);
                        continue;
                    }

                    let uri_str = doc_val
                        .and_then(|d| d.get("uri"))
                        .and_then(|u| u.as_str());

                    let file_path = uri_str.map(|u| {
                        let decoded = urlencoding::decode(u).unwrap_or_else(|_| u.into());
                        if decoded.starts_with("file://") {
                            decoded[7..].to_string()
                        } else {
                            decoded.to_string()
                        }
                    });

                    let resp = json!({
                        "jsonrpc": "2.0",
                        "id": id,
                        "result": {
                            "decorations": [],
                            "is_analyzed": false,
                            "path": file_path,
                            "status": "error"
                        }
                    });
                    send_response(&mut stdout, &resp);
                }
            }
            Some("rustowl/analyze") => {
                if let Some(id) = id {
                    if !is_initialized {
                        let resp = json!({
                            "jsonrpc": "2.0",
                            "id": id,
                            "error": {
                                "code": -32002,
                                "message": "Server not initialized"
                            }
                        });
                        send_response(&mut stdout, &resp);
                        continue;
                    }

                    let params = msg_val.get("params");
                    let is_valid = match params {
                        None => true,
                        Some(Value::Object(_)) => true,
                        Some(Value::Array(a)) => a.is_empty(),
                        _ => false,
