mod check;
mod clean;
mod completions;
mod logger;
mod lsp;
mod toolchain;

use completions::*;
use logger::set_quiet_level;
use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    let bin_name = args
        .get(0)
        .and_then(|p| std::path::Path::new(p).file_name())
        .and_then(|s| s.to_str())
        .unwrap_or("executable");

    // Handle argv[0] if invoked as rustowlc or cargo-rustowlc
    if bin_name == "rustowlc" || bin_name == "cargo-rustowlc" {
        print_rustowlc_usage(bin_name);
        std::process::exit(0);
    }

    // Parse options
    let mut quiet_count = 0;
    let mut stdio_flag = false;
    let mut version_flag = false;
    let mut help_flag = false;

    let mut subcommand: Option<String> = None;
    let mut sub_args: Vec<String> = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        if subcommand.is_some() {
            sub_args.push(arg.clone());
            i += 1;
            continue;
        }

        if arg == "-V" || arg == "--version" {
            version_flag = true;
        } else if arg == "-h" || arg == "--help" {
            help_flag = true;
        } else if arg == "--stdio" {
            stdio_flag = true;
        } else if arg == "-q" || arg == "--quiet" {
            quiet_count += 1;
        } else if arg.starts_with("-q") && arg.chars().skip(1).all(|c| c == 'q') {
            quiet_count += arg.len() - 1;
        } else if !arg.starts_with('-') {
            subcommand = Some(arg.clone());
        } else {
            // Unrecognized option
            eprintln!("error: unexpected argument '{}' found\n", arg);
            print_root_usage(bin_name);
            std::process::exit(2);
        }

        i += 1;
    }

    set_quiet_level(quiet_count);

    if version_flag {
        println!("RustOwl v1.0.0-rc.1");
        std::process::exit(0);
    }

    if help_flag && subcommand.is_none() {
        print_root_help(bin_name);
        std::process::exit(0);
    }

    if let Some(cmd) = subcommand {
