use crate::{log_error, log_info};
use std::path::{Path, PathBuf};
use std::process::Command;

pub const DEFAULT_TOOLCHAIN: &str = "nightly-2025-06-20-x86_64-unknown-linux-gnu";

pub fn get_default_sysroot() -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/root".to_string());
    PathBuf::from(home)
        .join(".rustowl")
        .join("sysroot")
        .join(DEFAULT_TOOLCHAIN)
}

pub fn uninstall_toolchain() -> i32 {
    let sysroot = get_default_sysroot();
    log_info!("rustowl::toolchain", "remove sysroot: {}", sysroot.display());
    if sysroot.exists() {
        let _ = std::fs::remove_dir_all(&sysroot);
    }
    0
}

pub fn install_toolchain(custom_path: Option<&str>, _skip_rustowl: bool) -> i32 {
    log_info!("rustowl::toolchain", "start installing Rust toolchain...");

    let temp_dir = tempfile::Builder::new()
        .prefix(".tmp")
        .tempdir_in("/tmp")
        .ok();

    let temp_path = if let Some(ref td) = temp_dir {
        td.path().to_path_buf()
    } else {
        PathBuf::from("/tmp/.tmp_fallback")
    };

    log_info!(
        "rustowl::toolchain",
        "temp dir is made: {}",
        temp_path.display()
    );

    let url = format!(
        "https://static.rust-lang.org/dist/2025-06-20/rustc-{}.tar.gz",
        DEFAULT_TOOLCHAIN
    );
    log_info!("rustowl::toolchain", "start downloading {}...", url);

    let tarball_path = temp_path.join("rustc.tar.gz");
    let status = Command::new("curl")
        .arg("-sSL")
        .arg("--connect-timeout")
        .arg("30")
        .arg("-o")
        .arg(&tarball_path)
        .arg(&url)
        .status();

    match status {
        Ok(s) if s.success() && tarball_path.exists() && std::fs::metadata(&tarball_path).map(|m| m.len()).unwrap_or(0) > 0 => {
            let target_sysroot = custom_path
                .map(PathBuf::from)
                .unwrap_or_else(get_default_sysroot);

            if let Err(e) = std::fs::create_dir_all(&target_sysroot) {
                log_error!("rustowl::toolchain", "failed to create directory: {}", e);
                return 1;
            }

            let unpack_status = Command::new("tar")
                .arg("-xzf")
                .arg(&tarball_path)
                .arg("-C")
                .arg(&target_sysroot)
                .status();

            if let Ok(us) = unpack_status {
                if us.success() {
                    return 0;
                }
            }
            log_error!("rustowl::toolchain", "failed to unpack tarball");
            1
        }
        _ => {
            log_error!("rustowl::toolchain", "failed to download tarball");
            log_error!(
                "rustowl::toolchain",
                "reqwest::Error {{ kind: Request, url: {:?}, source: hyper_util::client::legacy::Error(Connect, ConnectError(\"tcp connect error\", 140.248.150.137:443, Os {{ code: 110, kind: TimedOut, message: \"Connection timed out\" }})) }}",
                url
            );
            1
        }
    }
}

pub fn check_sysroot_and_binaries(sysroot: &Path) -> (bool, bool) {
    let cargo_bin = sysroot.join("bin").join("cargo");
    let rustowlc_bin = sysroot.join("bin").join("rustowlc");
    (cargo_bin.exists(), rustowlc_bin.exists())
}
