import subprocess, json, select, time, threading

p = subprocess.Popen(["./executable", "--stdio"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

def read_stderr():
    while True:
        line = p.stderr.readline()
        if not line: break
        print("STDERR:", line.decode("utf-8"), end="")

threading.Thread(target=read_stderr, daemon=True).start()

def send(msg):
    body = json.dumps(msg)
    data = f"Content-Length: {len(body)}\r\n\r\n{body}"
    p.stdin.write(data.encode("utf-8"))
    p.stdin.flush()

def read_one(timeout=1.0):
    r, _, _ = select.select([p.stdout], [], [], timeout)
    if not r:
        return None
    content_len = 0
    while True:
        line = p.stdout.readline().decode("utf-8")
        if not line: return None
        if line.startswith("Content-Length:"):
            content_len = int(line.split(":")[1].strip())
        if line == "\r\n":
            break
    body = p.stdout.read(content_len)
    return json.loads(body)

send({
    "jsonrpc": "2.0",
    "id": 1,
    "method": "initialize",
    "params": {
        "rootUri": "file:///tmp/test_project",
        "capabilities": {}
    }
})
init_resp = read_one()
print("Init resp:", init_resp)

send({"jsonrpc": "2.0", "method": "initialized", "params": {}})
time.sleep(0.1)

send({
    "jsonrpc": "2.0",
    "id": 2,
    "method": "rustowl/cursor",
    "params": {
        "document": {"uri": "file:///tmp/test_project/src/main.rs"},
        "position": {"line": 1, "character": 8}
    }
})
print("Cursor resp:", read_one())

send({
    "jsonrpc": "2.0",
    "id": 3,
    "method": "rustowl/analyze",
    "params": {}
})
print("Analyze resp:", read_one())

p.terminate()
'"}

