{"command":"cat << 'EOF' > src/check.rs
use crate::toolchain::{
    check_sysroot_and_binaries, get_default_sysroot, install_toolchain,
};
use crate::{log_error, log_info, log_warn};
use std::path::PathBuf;
use std::process::Command;

pub fn run_check(path: Option<&str>, _all_targets: bool, _all_features: bool) -> i32 {
    let raw_path = path.unwrap_or(".");
    let target_path = PathBuf::from(raw_path);

    // Canonicalize or resolve absolute path if possible
    let abs_path = target_path
        .canonicalize()
        .unwrap_or_else(|_| target_path.clone());

    // Validation: must exist, be a file, and have .rs extension
    let is_valid = abs_path.exists()
        && abs_path.is_file()
        && abs_path.extension().and_then(|s| s.to_str()) == Some("rs");

    let sysroot = get_default_sysroot();
    let sysroot_exists = sysroot.exists();

    if !sysroot_exists {
        log_info!(
            "rustowl::toolchain",
            "sysroot not found; start setup toolchain"
        );
        let _ = install_toolchain(None, false);
    }

    if !is_valid {
        log_warn!(
            "rustowl::lsp::analyze",
            "Invalid analysis target: {}",
            abs_path.display()
        );
        log_error!("rustowl", "Analyze failed");
        return 1;
    }

    let (has_cargo, has_rustowlc) = check_sysroot_and_binaries(&sysroot);
    if has_cargo {
        log_info!("rustowl::toolchain", "cargo is selected in sysroot/bin");
    } else {
        log_warn!("rustowl::toolchain", "cargo not found; fallback");
    }

    if has_rustowlc {
        log_info!("rustowl::toolchain", "rustowlc is selected in sysroot/bin");
    } else {
        log_warn!("rustowl::toolchain", "rustowlc not found; fallback");
    }

    log_info!("rustowl::lsp::backend", "wait 100ms for rust-analyzer");
    std::thread::sleep(std::time::Duration::from_millis(100));

    log_info!("rustowl::lsp::backend", "stop running analysis processes");
    log_info!("rustowl::lsp::backend", "start analysis");
    log_info!("rustowl::lsp::backend", "analyze 1 packages...");

    if has_rustowlc {
        log_info!("rustowl::toolchain", "rustowlc is selected in sysroot/bin");
    }

    log_info!(
        "rustowl::lsp::analyze",
        "start analyzing {}",
        abs_path.display()
    );

    let rustowlc_bin = sysroot.join("bin").join("rustowlc");

    let mut cmd = if has_rustowlc {
        let mut c = Command::new(&rustowlc_bin);
        c.arg(format!("--sysroot={}", sysroot.display()))
            .arg("--crate-type=lib")
            .arg("-o/dev/null")
            .arg(&abs_path);
        c
    } else {
        let mut c = Command::new("cargo");
        c.arg("rustowlc");
        c
    };

    cmd.env(
        "CARGO_ENCODED_RUSTFLAGS",
        format!("--sysroot={}", sysroot.display()),
    );
    cmd.env(
        "LD_LIBRARY_PATH",
        format!("{}/lib:", sysroot.display()),
    );
    cmd.env("RUSTC_BOOTSTRAP", "1");

    let status = cmd.status();

    log_info!("rustowl::lsp::analyze", "stdout closed");

    match status {
        Ok(s) if s.success() => 0,
        _ => {
            log_error!("rustowl", "Analyze failed");
            1
        }
    }
}
